@keyframes nc-sweep { to { top: 104%; } }
@keyframes nc-spin { to { transform: rotate(360deg); } }
@keyframes nc-blink { 0%, 58% { opacity: 1; } 59%, 100% { opacity: .12; } }
@keyframes nc-glitch-a {
  0%, 86%, 100% { opacity: 0; transform: translate(0, 0); }
  87% { opacity: .85; transform: translate(-7px, -2px); }
  89% { opacity: .85; transform: translate(4px, 1px); }
  91% { opacity: 0; }
  95% { opacity: .6; transform: translate(-3px, 2px); }
  96% { opacity: 0; }
}
@keyframes nc-glitch-b {
  0%, 90%, 100% { opacity: 0; transform: translate(0, 0); }
  91% { opacity: .8; transform: translate(8px, 2px); }
  93% { opacity: .8; transform: translate(-3px, -1px); }
  95% { opacity: 0; }
}

@media (prefers-reduced-motion: reduce) {
  *, *:before, *:after {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }
}

/* ==================================================================
   EDGERUNNERS / BILLBOARD LAYER
   Cel-print halftone, comic ink panels and neon signboard controls.
   ================================================================== */

:root {
  --nc-ink3: #07070d;
  --nc-paper: #f2ede2;
  --nc-cyan-deep: #0aa7c4;
}

/* ---------- world: print halftone + cel grade ---------- */
.nc-city {
